255	+func configureRepoIdentity(ctx context.Context) (owner, repo, cleanRemote string, err error) {
256	+	raw, err := gitremote.GetRemoteURL(ctx, defaultMirrorRemote)
257	+	if err != nil {
258	+		return "", "", "", fmt.Errorf("read origin remote: %w", err)
259	+	}
260	+	info, err := gitremote.ParseURL(raw)
261	+	if err != nil {
262	+		return "", "", "", fmt.Errorf("parse origin remote: %w", err)
263	+	}
264	+	if info.Forge != mirrorUseForge {
265	+		return "", "", "", errors.New("interactive configure currently requires a GitHub origin remote")
266	+	}
267	+	clean, err := cleanRemoteURLForReport(raw)
268	+	if err != nil {
269	+		return "", "", "", err
270	+	}
271	+	return strings.ToLower(info.Owner), strings.ToLower(info.Repo), clean, nil
272	+}
