274	+func ensureConfigureLogin(ctx context.Context, outW, errW io.Writer, deps configureFlowDeps) (*authProfile, error) {
275	+	target, err := deps.resolveAuth(ctx)
276	+	if err != nil {
277	+		return nil, err
278	+	}
279	+	if target.token != "" {
280	+		if err := api.RequireSecureURL(target.coreURL); err != nil {
281	+			return nil, fmt.Errorf("context login server URL check: %w", err)
282	+		}
283	+		if profile, profileErr := deps.fetchProfile(ctx, target.coreURL, target.token); profileErr == nil {
284	+			return profile, nil
285	+		} else if !isKeychainTokenRejected(profileErr) {
286	+			return nil, fmt.Errorf("validate login: %w", profileErr)
287	+		}
288	+	}
289	+
290	+	if err := deps.runLogin(ctx, outW, errW); err != nil {
291	+		return nil, fmt.Errorf("login: %w", err)
292	+	}
293	+	target, err = deps.resolveAuth(ctx)
294	+	if err != nil {
295	+		return nil, err
296	+	}
297	+	if target.token == "" {
298	+		return nil, errors.New("login completed without an active session")
299	+	}
300	+	if err := api.RequireSecureURL(target.coreURL); err != nil {
301	+		return nil, fmt.Errorf("context login server URL check: %w", err)
302	+	}
303	+	profile, err := deps.fetchProfile(ctx, target.coreURL, target.token)
304	+	if err != nil {
305	+		return nil, fmt.Errorf("validate login: %w", err)
306	+	}
307	+	fmt.Fprintf(outW, "✓ Logged in as %s\n", profile.Handle)
308	+	return profile, nil
309	+}
