311	+func ensureConfigureRepoAccess(ctx context.Context, outW, errW io.Writer, reporter configureAccessReporter, initial *api.EnableRepoResponse, cleanRemote, owner, repo string, deps configureFlowDeps) error {
312	+	fmt.Fprintf(errW, "✗ Entire has no access to %s/%s\n\n", owner, repo)
313	+	installURL := strings.TrimSpace(initial.InstallURL)
314	+	if installURL == "" {
315	+		installURL = fmt.Sprintf("%s/install?repo=%s%%2F%s", configureWebBaseURL(), url.PathEscape(owner), url.PathEscape(repo))
316	+	}
317	+
318	+	admin, adminErr := deps.githubAdmin(ctx, owner, repo)
319	+	if adminErr == nil && !admin {
320	+		fmt.Fprintln(errW, "  An admin needs to install the GitHub app first.")
321	+		fmt.Fprintln(errW, "  Send them this link to continue:")
322	+		fmt.Fprintf(errW, "\n  %s\n", installURL)
323	+		return NewSilentError(errors.New("GitHub app installation required"))
324	+	}
325	+	if adminErr != nil {
326	+		switch {
327	+		case errors.Is(adminErr, errConfigureGHUnavailable):
328	+			fmt.Fprintln(errW, "  Could not verify GitHub admin access because the gh CLI is not installed.")
329	+			fmt.Fprintln(errW, "  Install it from https://cli.github.com/ and run `gh auth login` for future checks.")
330	+		case errors.Is(adminErr, errConfigureGHUnauthenticated):
331	+			fmt.Fprintln(errW, "  Could not verify GitHub admin access because the gh CLI is not authenticated.")
332	+			fmt.Fprintln(errW, "  Run `gh auth login` for future checks.")
333	+		default:
334	+			fmt.Fprintf(errW, "  Could not verify GitHub admin access: %v\n", adminErr)
335	+		}
336	+		fmt.Fprintln(errW, "  If you administer this repository, you can still continue with the installation link.")
337	+		fmt.Fprintln(errW)
338	+	}
339	+
340	+	fmt.Fprintln(outW, "  Install the GitHub app to grant access:")
341	+	fmt.Fprintf(outW, "  %s\n\n", installURL)
342	+	if err := deps.openURL(ctx, installURL); err != nil {
343	+		fmt.Fprintln(outW, "  Open the link above in your browser.")
344	+	}
345	+	stop := startSpinner(errW, "Waiting for installation")
346	+	stopped := false
347	+	defer func() {
348	+		if !stopped {
349	+			stop(false)
350	+		}
351	+	}()
352	+
353	+	waitCtx, cancel := context.WithTimeout(ctx, configureAccessWaitTimeout)
354	+	defer cancel()
355	+	ticker := time.NewTicker(configureAccessPollInterval)
356	+	defer ticker.Stop()
357	+	for {
358	+		select {
359	+		case <-waitCtx.Done():
360	+			return fmt.Errorf("waiting for GitHub app installation: %w", waitCtx.Err())
361	+		case <-ticker.C:
362	+			access, err := reporter.ReportEnable(waitCtx, cleanRemote)
363	+			if err == nil && access.Connected {
364	+				stop(true)
365	+				stopped = true
366	+				fmt.Fprintln(outW, "✓ Access granted")
367	+				return nil
368	+			}
369	+		}
370	+	}
371	+}
