373	+func configureGitHubAdmin(ctx context.Context, owner, repo string) (bool, error) {
374	+	runner := execRunner{}
375	+	if !ghAvailable(ctx, runner) {
376	+		return false, errConfigureGHUnavailable
377	+	}
378	+	if !ghAuthenticated(ctx, runner) {
379	+		return false, errConfigureGHUnauthenticated
380	+	}
381	+	out, err := runner.Run(ctx, "gh", "api", "repos/"+owner+"/"+repo, "--jq", ".permissions.admin")
382	+	if err != nil {
383	+		return false, fmt.Errorf("check GitHub admin permission: %w", err)
384	+	}
385	+	admin, err := strconv.ParseBool(strings.TrimSpace(out))
386	+	if err != nil {
387	+		return false, fmt.Errorf("parse GitHub admin permission: %w", err)
388	+	}
389	+	return admin, nil
390	+}
