392	+func configureCreateMirrors(ctx context.Context, outW, errW io.Writer, client *coreapi.Client, owner, repo, jurisdiction string) ([]coreapi.ResolvedPlacement, error) {
393	+	regions, err := availableRegions(ctx, client)
394	+	if err != nil {
395	+		return nil, fmt.Errorf("list regions: %w", err)
396	+	}
397	+	if len(regions) == 0 {
398	+		return nil, errors.New("no regions available to mirror into")
399	+	}
400	+	selected, err := pickConfigureRegions(ctx, outW, regions, jurisdiction)
401	+	if err != nil {
402	+		return nil, err
403	+	}
404	+	results := createMirrors(ctx, errW, mirrorTargets([]coreapi.AvailableMirror{{Owner: owner, Repo: repo}}, selected), false, 30*time.Minute)
405	+	reportErr := reportMirrorResults(outW, errW, results)
406	+	placements := configureSuccessfulMirrorPlacements(selected, results)
407	+	if len(placements) > 0 {
408	+		if reportErr != nil {
409	+			fmt.Fprintf(errW, "Continuing with %d mirror(s) that succeeded.\n", len(placements))
410	+		}
411	+		return placements, nil
412	+	}
413	+	if reportErr != nil {
414	+		return nil, reportErr
415	+	}
416	+	return nil, errors.New("no usable mirrors were created")
417	+}
418	+
419	+func configureSuccessfulMirrorPlacements(selected []regionChoice, results []mirrorResult) []coreapi.ResolvedPlacement {
420	+	placements := make([]coreapi.ResolvedPlacement, 0, len(results))
421	+	for i, result := range results {
422	+		if i >= len(selected) || result.err != nil || result.cloneURL == "" {
423	+			continue
424	+		}
425	+		region := selected[i]
426	+		placements = append(placements, coreapi.ResolvedPlacement{
427	+			ClusterHost:  region.host,
428	+			Cell:         coreapi.NewOptString(region.slug),
429	+			Jurisdiction: coreapi.NewOptString(region.jurisdiction),
430	+		})
431	+	}
432	+	return placements
433	+}
