435	+func pickConfigureRegions(ctx context.Context, outW io.Writer, regions []regionChoice, jurisdiction string) ([]regionChoice, error) {
436	+	opts, defaults := clusterChoices(regions, jurisdiction)
437	+	byHost := make(map[string]regionChoice, len(regions))
438	+	for _, region := range regions {
439	+		byHost[region.host] = region
440	+	}
441	+	selected := append([]string(nil), defaults...)
442	+	form := NewAccessibleForm(huh.NewGroup(
443	+		huh.NewMultiSelect[string]().
444	+			Title("Which regions should this repository live in?").
445	+			Description("Space to select, enter to confirm — your data stays in the selected regions.").
446	+			Options(opts...).
447	+			Height(multiSelectHeight(len(opts))).
448	+			Validate(func(values []string) error {
449	+				if len(values) == 0 {
450	+					return errors.New("select at least one region")
451	+				}
452	+				return nil
453	+			}).
454	+			Value(&selected),
455	+	))
456	+	if err := form.RunWithContext(ctx); err != nil {
457	+		if cancelErr := handleFormCancellation(outW, "Configure", err); cancelErr != nil {
458	+			return nil, cancelErr
459	+		}
460	+		return nil, NewSilentError(errors.New("configure cancelled"))
461	+	}
462	+	chosen := make([]regionChoice, 0, len(selected))
463	+	for _, host := range selected {
464	+		if region, ok := byHost[host]; ok {
465	+			chosen = append(chosen, region)
466	+		}
467	+	}
468	+	return chosen, nil
469	+}
