511	+func (field *configureUpstreamField) Update(msg tea.Msg) (huh.Model, tea.Cmd) {
512	+	if keyMsg, ok := msg.(tea.KeyPressMsg); ok {
513	+		switch {
514	+		case configureRadioSelectKey(keyMsg.String()):
515	+			field.commitHighlighted()
516	+			return field, configureWindowResize(field.window)
517	+		case configureNextKey(keyMsg.String()):
518	+			// Enter continues with the intentionally selected value. Merely moving
519	+			// the cursor does not change the radio selection.
520	+			return field, huh.NextField
521	+		}
522	+	}
523	+	if size, ok := msg.(tea.WindowSizeMsg); ok {
524	+		field.window = size
525	+	}
526	+	model, cmd := field.Select.Update(msg)
527	+	if updated, ok := model.(*huh.Select[string]); ok {
528	+		field.Select = updated
529	+	}
530	+	_, movedCursor := msg.(tea.KeyPressMsg)
531	+	field.preserveCommittedSelection(movedCursor)
532	+	return field, cmd
533	+}
