1079	+			return "", fmt.Errorf("read origin remote URL: %w", err)
1080	+		}
1081	+	}
1082	+
1083	+	forgeRemote, err := configureExistingForgeRemote(ctx, repoRoot, owner, repo, remotes, defaultMirrorRemote)
1084	+	if err != nil {
1085	+		return "", err
1086	+	}
1087	+	preserve := ""
1088	+	if info, parseErr := gitremote.ParseURL(current); parseErr == nil && info.Protocol != gitremote.ProtocolEntire {
1089	+		if forgeRemote == "" {
1090	+			preserve = availableConfigureRemoteName(remotes, defaultMirrorUpstreamRemote, mirrorCloneProviderGitHub)
1091	+			forgeRemote = preserve
1092	+		}
1093	+	}
1094	+	if forgeRemote == "" {
1095	+		forgeRemote = availableConfigureRemoteName(remotes, mirrorCloneProviderGitHub)
1096	+		forgeURL := fmt.Sprintf("https://github.com/%s/%s.git", owner, repo)
1097	+		if _, err := gitRunner(ctx, repoRoot, "remote", "add", forgeRemote, forgeURL); err != nil {
1098	+			return "", fmt.Errorf("add GitHub push remote %q: %w", forgeRemote, err)
1099	+		}
1100	+		remotes[forgeRemote] = true
1101	+		fmt.Fprintf(outW, "✓ Added GitHub push remote %q\n  %s\n", forgeRemote, forgeURL)
1102	+	}
1103	+
1104	+	mirrorURL := mirrorCloneURL(chosen.ClusterHost, owner, repo)
1105	+	plan := planMirrorRemote(defaultMirrorRemote, mirrorURL, current, preserve, remotes)
1106	+	if err := applyMirrorRemotePlan(ctx, repoRoot, plan); err != nil {
1107	+		return "", err
1108	+	}
1109	+	// Report the replaced URL and where it remains reachable. The returned
1110	+	// forgeRemote is deliberately separate from the mirror fetch remote: config
1111	+	// commits must land on GitHub, never in the one-way Entire mirror.
1112	+	reportMirrorRemotePlan(outW, errW, plan)
1113	+	return forgeRemote, nil
1114	+}
1115	+
1116	+func configureExistingForgeRemote(ctx context.Context, repoRoot, owner, repo string, remotes map[string]bool, exclude string) (string, error) {
1117	+	names := make([]string, 0, len(remotes))
1118	+	for name := range remotes {
1119	+		if name != exclude {
1120	+			names = append(names, name)
1121	+		}
1122	+	}
1123	+	sort.SliceStable(names, func(i, j int) bool {
1124	+		priority := func(name string) int {
1125	+			switch name {
1126	+			case mirrorCloneProviderGitHub:
1127	+				return 0
1128	+			case defaultMirrorUpstreamRemote:
1129	+				return 1
1130	+			default:
1131	+				return 2
1132	+			}
1133	+		}
1134	+		if priority(names[i]) != priority(names[j]) {
1135	+			return priority(names[i]) < priority(names[j])
1136	+		}
1137	+		return names[i] < names[j]
1138	+	})
1139	+	for _, name := range names {
1140	+		raw, err := gitremote.GetRemoteURLInDir(ctx, repoRoot, name)
1141	+		if err != nil {
1142	+			return "", fmt.Errorf("read remote %q URL: %w", name, err)
1143	+		}
1144	+		info, err := gitremote.ParseURL(raw)
1145	+		if err == nil && info.Protocol != gitremote.ProtocolEntire && info.Forge == mirrorUseForge &&
1146	+			strings.EqualFold(info.Owner, owner) && strings.EqualFold(info.Repo, repo) {
1147	+			return name, nil
1148	+		}
1149	+	}
1150	+	return "", nil
1151	+}
1152	+
1153	+func availableConfigureRemoteName(remotes map[string]bool, candidates ...string) string {
1154	+	for _, candidate := range candidates {
1155	+		if !remotes[candidate] {
1156	+			return candidate
1157	+		}
1158	+	}
1159	+	for i := 2; ; i++ {
1160	+		candidate := fmt.Sprintf("github-%d", i)
1161	+		if !remotes[candidate] {
1162	+			return candidate
1163	+		}
1164	+	}
1165	+}
1166	+
1167	+// configureGitChanges returns porcelain status keyed by path. Its values retain
1168	+// XY so callers can detect whether anything was already staged before the flow.
1169	+func configureGitChanges(ctx context.Context, repoRoot string) (map[string]string, error) {
1170	+	out, err := gitRunner(ctx, repoRoot, "status", "--porcelain=v1", "--untracked-files=all")
1171	+	if err != nil {
1172	+		return nil, fmt.Errorf("read git status: %w", err)
1173	+	}
1174	+	changes := make(map[string]string)
1175	+	for _, line := range strings.Split(out, "\n") {
1176	+		if len(line) < 4 {
1177	+			continue
1178	+		}
1179	+		path := strings.TrimSpace(line[3:])
1180	+		if arrow := strings.LastIndex(path, " -> "); arrow >= 0 {
1181	+			path = path[arrow+4:]
1182	+		}
1183	+		if path != "" {
1184	+			changes[path] = line[:2]
1185	+		}
1186	+	}
1187	+	return changes, nil
1188	+}
1189	+
1190	+func newConfigureChanges(before, after map[string]string) []string {
1191	+	paths := make([]string, 0, len(after))
1192	+	for path := range after {
1193	+		if _, existed := before[path]; !existed {
1194	+			paths = append(paths, path)
1195	+		}
1196	+	}
1197	+	sort.Strings(paths)
1198	+	return paths
1199	+}
1200	+
1201	+func configureSaveAndPush(cmd *cobra.Command, repoRoot, owner, repo string, before map[string]string, generated []string, branch string, protected bool, choice, forgeRemote string, now func() time.Time) error {
1202	+	outW := cmd.OutOrStdout()
1203	+	if len(generated) == 0 {
1204	+		fmt.Fprintln(outW, "  No new configuration changes to commit.")
1205	+		return nil
1206	+	}
1207	+	if len(before) != 0 {
1208	+		fmt.Fprintln(outW, "  Configuration was saved but not committed because the worktree already had changes.")
1209	+		fmt.Fprintln(outW, "  Review and commit the configuration normally when ready.")
1210	+		return nil
1211	+	}
1212	+
1213	+	if branch == "" {
1214	+		return errors.New("cannot save configuration from a detached HEAD")
1215	+	}
1216	+	if protected && choice == configureSaveDirect {
1217	+		return fmt.Errorf("%s is protected; push to a new branch", branch)
1218	+	}
1219	+	if choice != configureSaveDirect && choice != configureSaveNewBranch {
1220	+		return fmt.Errorf("unknown save choice %q", choice)
1221	+	}
1222	+	if forgeRemote == "" {
1223	+		return errors.New("no GitHub remote available for configuration push")
1224	+	}
1225	+
1226	+	pushBranch := branch
1227	+	if choice == configureSaveNewBranch {
1228	+		var err error
1229	+		pushBranch, err = availableConfigureBranch(cmd.Context(), repoRoot, now)
1230	+		if err != nil {
1231	+			return err
1232	+		}
1233	+		if _, err := gitRunner(cmd.Context(), repoRoot, "switch", "-c", pushBranch); err != nil {
1234	+			return fmt.Errorf("create configuration branch: %w", err)
1235	+		}
1236	+	}
1237	+
1238	+	args := []string{"add", "--"}
1239	+	args = append(args, generated...)
1240	+	if _, err := gitRunner(cmd.Context(), repoRoot, args...); err != nil {
1241	+		return fmt.Errorf("stage configuration: %w", err)
1242	+	}
1243	+	if _, err := gitRunner(cmd.Context(), repoRoot, "commit", "-m", configureCommitMessage); err != nil {
1244	+		return fmt.Errorf("commit configuration: %w", err)
1245	+	}
1246	+	sha, err := gitRunner(cmd.Context(), repoRoot, "rev-parse", "--short", "HEAD")
1247	+	if err != nil {
1248	+		return fmt.Errorf("read configuration commit: %w", err)
1249	+	}
1250	+	fmt.Fprintf(outW, "✓ Committed %s · %s\n", configureCommitMessage, sha)
1251	+	if _, err := gitRunner(cmd.Context(), repoRoot, "push", "-u", forgeRemote, pushBranch); err != nil {
1252	+		return fmt.Errorf("push configuration to GitHub remote %q: %w", forgeRemote, err)
1253	+	}
1254	+	fmt.Fprintf(outW, "✓ Pushed to %s/%s\n", forgeRemote, pushBranch)
1255	+	if choice == configureSaveNewBranch {
1256	+		fmt.Fprintln(outW, "  Open a trail to merge it:")
1257	+		fmt.Fprintf(outW, "  %s/gh/%s/%s/trails/new?branch=%s\n", configureWebBaseURL(), url.PathEscape(owner), url.PathEscape(repo), url.QueryEscape(pushBranch))
1258	+	}
1259	+	return nil
1260	+}
1261	+
1262	+func configureBranchHasNoUnpushedCommits(ctx context.Context, repoRoot string) bool {
1263	+	// @{u} is the branch's configured upstream before configure rewrites any
1264	+	// remotes. If it does not exist, we cannot prove a direct push is isolated to
1265	+	// the generated config commit, so only the new-branch action is safe.
1266	+	upstream, err := gitRunner(ctx, repoRoot, "rev-parse", "--abbrev-ref", "--symbolic-full-name", "@{u}")
1267	+	if err != nil || upstream == "" {
1268	+		return false
1269	+	}
1270	+	ahead, err := gitRunner(ctx, repoRoot, "rev-list", "--count", upstream+"..HEAD")
1271	+	if err != nil {
1272	+		return false
1273	+	}
1274	+	count, err := strconv.Atoi(strings.TrimSpace(ahead))
1275	+	return err == nil && count == 0
1276	+}
1277	+
1278	+func configureBranchProtected(ctx context.Context, owner, repo, branch string) (bool, error) {
1279	+	// GitHub's branch `.protected` flag is true for *any* active ruleset rule.
1280	+	// A non-blocking rule such as Copilot code review therefore made ordinary
1281	+	// feature branches look push-protected. Inspect the effective rules instead
1282	+	// and only require a new branch for rules that can reject a direct update.
1283	+	out, err := exec.CommandContext(ctx, "gh", "api", "repos/"+owner+"/"+repo+"/rules/branches/"+url.PathEscape(branch)).Output()
1284	+	if err != nil {
1285	+		return false, fmt.Errorf("check GitHub branch rules: %w", err)
1286	+	}
1287	+	return configureRulesBlockDirectPush(out)
1288	+}
1289	+
1290	+func configureRulesBlockDirectPush(raw []byte) (bool, error) {
1291	+	var rules []struct {
1292	+		Type string `json:"type"`
1293	+	}
1294	+	if err := json.Unmarshal(raw, &rules); err != nil {
1295	+		return false, fmt.Errorf("parse GitHub branch rules: %w", err)
1296	+	}
1297	+	for _, rule := range rules {
1298	+		switch rule.Type {
1299	+		case "pull_request", "required_status_checks", "required_deployments", "update", "workflows":
1300	+			return true, nil
1301	+		}
1302	+	}
1303	+	return false, nil
1304	+}
1305	+
1306	+func availableConfigureBranch(ctx context.Context, repoRoot string, now func() time.Time) (string, error) {
1307	+	candidates := []string{configureBranchBase, configureBranchBase + "-" + now().Format("20060102-150405")}
1308	+	for _, candidate := range candidates {
1309	+		_, err := gitRunner(ctx, repoRoot, "show-ref", "--verify", "--quiet", "refs/heads/"+candidate)
1310	+		if err == nil {
1311	+			continue // branch already exists
1312	+		}
1313	+		var exitErr *exec.ExitError
1314	+		if errors.As(err, &exitErr) && exitErr.ExitCode() == 1 {
1315	+			return candidate, nil // show-ref uses 1 for a missing ref
1316	+		}
1317	+		return "", fmt.Errorf("check configuration branch %q: %w", candidate, err)
1318	+	}
1319	+	return "", errors.New("could not choose an unused configuration branch name")
1320	+}
